#include <stdio.h>
#include <stdlib.h>

#define MAXN 50

int x[MAXN], y[MAXN];
int parent[MAXN];

int find(int a) {
    while (parent[a] != a) {
        parent[a] = parent[parent[a]];
        a = parent[a];
    }
    return a;
}

void unite(int a, int b) {
    a = find(a); b = find(b);
    if (a != b) parent[a] = b;
}

int main() {
    int N;
    scanf("%d", &N);
    for (int i = 0; i < N; i++) {
        scanf("%d %d", &x[i], &y[i]);
    }

    int ans = N; // worst case: each ball alone

    // try all possible (p,q) from differences between any two balls
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (i == j) continue;
            int p = x[i] - x[j];
            int q = y[i] - y[j];
            // skip (0,0) which never happens because i != j and points are distinct? Not guaranteed distinct but we skip
            if (p == 0 && q == 0) continue;

            // initialize union-find
            for (int k = 0; k < N; k++) parent[k] = k;

            // connect all pairs with difference (p,q) or (-p,-q)
            for (int a = 0; a < N; a++) {
                for (int b = 0; b < N; b++) {
                    if (a == b) continue;
                    if ((x[a] - x[b] == p && y[a] - y[b] == q) ||
                        (x[a] - x[b] == -p && y[a] - y[b] == -q)) {
                        unite(a, b);
                    }
                }
            }

            // count components
            int comps = 0;
            for (int k = 0; k < N; k++) {
                if (find(k) == k) comps++;
            }
            if (comps < ans) ans = comps;
        }
    }

    printf("%d\n", ans);
    return 0;
}

