// Hash set for coordinates
typedef struct { int x, y, used; } Entry;
Entry table[1<<21];
int tsize = 1<<21;

void ht_clear() { memset(table, 0, sizeof(table)); }
int ht_hash(int x, int y) { return (unsigned)((x*1000003LL + y) * 2654435761ULL) & (tsize-1); }
void ht_insert(int x, int y) {
    int h = ht_hash(x,y);
    while(table[h].used && !(table[h].x==x && table[h].y==y)) h=(h+1)&(tsize-1);
    table[h].used=1; table[h].x=x; table[h].y=y;
}
int ht_find(int x, int y) {
    int h = ht_hash(x,y);
    while(table[h].used) { if(table[h].x==x && table[h].y==y) return 1; h=(h+1)&(tsize-1); }
    return 0;
}

