#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    ll x, y;
} Point;

int cmp_point(const void *a, const void *b) {
    const Point *p = (const Point *)a;
    const Point *q = (const Point *)b;
    if (p->x != q->x) return (p->x < q->x) ? -1 : 1;
    if (p->y != q->y) return (p->y < q->y) ? -1 : 1;
    return 0;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Point *pts = (Point *)malloc(sizeof(Point) * N);
    for (int i = 0; i < N; i++) {
        scanf("%lld %lld", &pts[i].x, &pts[i].y);
    }

    qsort(pts, N, sizeof(Point), cmp_point);

    int ans = N;

    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            ll p = pts[j].x - pts[i].x;
            ll q = pts[j].y - pts[i].y;

            int cost = 0;
            int prev = 0;

            for (int k = 0; k < N; k++) {
                if (prev >= N) {
                    cost++;
                    continue;
                }

                ll tx = pts[k].x - p;
                ll ty = pts[k].y - q;

                while (prev < N && (pts[prev].x < tx || (pts[prev].x == tx && pts[prev].y < ty))) {
                    prev++;
                }

                if (prev < N && pts[prev].x == tx && pts[prev].y == ty) {
                    // can be collected with cost 0 after its predecessor
                } else {
                    cost++;
                }
            }

            if (cost < ans) ans = cost;
        }
    }

    printf("%d\n", ans);

    free(pts);
    return 0;
}

