int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<pair<long long,long long>> pt(N);
    for (int i = 0; i < N; ++i) cin >> pt[i].first >> pt[i].second;

    if (N == 1) {
        cout << 1 << '\n';
        return 0;
    }

    int ans = N;

    // Try every possible vector (p, q) formed by two balls.
    // For a fixed vector, cost equals number of connected components
    // in the directed graph where an edge u -> v exists if v = u + (p,q).
    // Since each node has indegree/outdegree at most 1, this is just
    // counting balls that do not have a predecessor by (-p,-q).
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (i == j) continue;
            long long p = pt[j].first - pt[i].first;
            long long q = pt[j].second - pt[i].second;

            int cost = 0;
            for (int k = 0; k < N; ++k) {
                bool hasPred = false;
                long long tx = pt[k].first - p;
                long long ty = pt[k].second - q;
                for (int t = 0; t < N; ++t) {
                    if (pt[t].first == tx && pt[t].second == ty) {
                        hasPred = true;
                        break;
                    }
                }
                if (!hasPred) ++cost;
            }
            ans = min(ans, cost);
        }
    }

    cout << ans << '\n';
    return 0;
}

