public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int[] x = new int[N];
        int[] y = new int[N];
        for (int i = 0; i < N; i++) {
            x[i] = sc.nextInt();
            y[i] = sc.nextInt();
        }

        if (N == 1) {
            System.out.println(1);
            return;
        }

        Map<String, Integer> freq = new HashMap<>();
        int maxFreq = 0;

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (i == j) continue;
                int dx = x[j] - x[i];
                int dy = y[j] - y[i];
                int g = gcd(Math.abs(dx), Math.abs(dy));
                dx /= g;
                dy /= g;
                // Normalize sign: make first non-zero positive
                if (dx < 0 || (dx == 0 && dy < 0)) {
                    dx = -dx;
                    dy = -dy;
                }
                String key = dx + "," + dy;
                int count = freq.getOrDefault(key, 0) + 1;
                freq.put(key, count);
                if (count > maxFreq) {
                    maxFreq = count;
                }
            }
        }

        System.out.println(N - maxFreq);
    }

    static int gcd(int a, int b) {
        while (b != 0) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
}

