import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        long[] x = new long[N];
        long[] y = new long[N];
        for (int i = 0; i < N; i++) {
            x[i] = fs.nextLong();
            y[i] = fs.nextLong();
        }

        if (N == 1) {
            System.out.println(1);
            return;
        }

        // Compress points to indices
        HashMap<Long, Integer> idMap = new HashMap<>();
        for (int i = 0; i < N; i++) {
            idMap.put(pack(x[i], y[i]), i);
        }

        int answer = N; // choosing any invalid chain gives cost N at worst

        // Try every possible non-zero vector (p, q) formed by two balls
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (i == j) continue;
                long p = x[j] - x[i];
                long q = y[j] - y[i];
                if (p == 0 && q == 0) continue;

                int starts = 0;
                for (int k = 0; k < N; k++) {
                    long prevKey = pack(x[k] - p, y[k] - q);
                    if (!idMap.containsKey(prevKey)) {
                        starts++;
                    }
                }
                answer = Math.min(answer, starts);
            }
        }

        System.out.println(answer);
    }

    static long pack(long a, long b) {
        return (a << 32) ^ (b & 0xffffffffL);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

import sys

def main():
    input = sys.stdin.readline
    N = int(input())
    pts = [tuple(map(int, input().split())) for _ in range(N)]

    if N == 1:
        print(1)
        return

    # Candidate vectors (p, q): difference between two balls
    candidates = set()
    for i in range(N):
        xi, yi = pts[i]
        for j in range(N):
            if i == j:
                continue
            xj, yj = pts[j]
            candidates.add((xj - xi, yj - yi))

    ans = N
    point_set = set(pts)

    for p, q in candidates:
        cost = 0
        for x, y in pts:
            # This point must start a new chain if there is no predecessor by (-p, -q)
            if (x - p, y - q) not in point_set:
                cost += 1
        if cost < ans:
            ans = cost

    print(ans)

